const CK="A01MrKo9pr6QYu0TkRtJxr8NP", CS="y1vhWndL84ebE74T2UuKh9DH4yawG54FnOHAPA4I7QafH9si6U", AT="{{X_ACCOUNT_ID}}-Lci3hOAjyo99nIX5xfi0A14IViDXvl", AS="LrXyt1KIxKIzNEHWhkj90C7rszXxYQHToDaHDd7u8jL9T";
const H=this.helpers;
// Pure-JS SHA-1 + HMAC-SHA1 over byte arrays. Returns base64 of the 20-byte MAC.
function _sha1(bytes){
  function rotl(n,s){return (n<<s)|(n>>>(32-s));}
  var ml=bytes.length*8;
  var withOne=bytes.concat([0x80]);
  while(withOne.length%64!==56) withOne.push(0);
  for(var i=7;i>=0;i--) withOne.push((ml/Math.pow(2,i*8))&0xff);
  var h0=0x67452301,h1=0xEFCDAB89,h2=0x98BADCFE,h3=0x10325476,h4=0xC3D2E1F0;
  for(var off=0;off<withOne.length;off+=64){
    var w=new Array(80);
    for(var t=0;t<16;t++){var j=off+t*4;w[t]=((withOne[j]<<24)|(withOne[j+1]<<16)|(withOne[j+2]<<8)|(withOne[j+3]))|0;}
    for(var t=16;t<80;t++){w[t]=rotl(w[t-3]^w[t-8]^w[t-14]^w[t-16],1);}
    var a=h0,b=h1,c=h2,d=h3,e=h4;
    for(var t=0;t<80;t++){
      var f,k;
      if(t<20){f=(b&c)|((~b)&d);k=0x5A827999;}
      else if(t<40){f=b^c^d;k=0x6ED9EBA1;}
      else if(t<60){f=(b&c)|(b&d)|(c&d);k=0x8F1BBCDC;}
      else{f=b^c^d;k=0xCA62C1D6;}
      var tmp=(rotl(a,5)+f+e+k+w[t])|0;
      e=d;d=c;c=rotl(b,30);b=a;a=tmp;
    }
    h0=(h0+a)|0;h1=(h1+b)|0;h2=(h2+c)|0;h3=(h3+d)|0;h4=(h4+e)|0;
  }
  var out=[];[h0,h1,h2,h3,h4].forEach(function(h){out.push((h>>>24)&0xff,(h>>>16)&0xff,(h>>>8)&0xff,h&0xff);});
  return out;
}
function _strBytes(s){var b=[];for(var i=0;i<s.length;i++){var c=s.charCodeAt(i); if(c<128)b.push(c); else if(c<2048){b.push(192|(c>>6),128|(c&63));} else {b.push(224|(c>>12),128|((c>>6)&63),128|(c&63));}}return b;}
function _b64(bytes){var t='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';var o='';for(var i=0;i<bytes.length;i+=3){var b0=bytes[i],b1=i+1<bytes.length?bytes[i+1]:0,b2=i+2<bytes.length?bytes[i+2]:0;o+=t[b0>>2]+t[((b0&3)<<4)|(b1>>4)];o+=(i+1<bytes.length)?t[((b1&15)<<2)|(b2>>6)]:'=';o+=(i+2<bytes.length)?t[b2&63]:'=';}return o;}
function hmacSha1B64(key,msg){
  var kb=_strBytes(key);
  if(kb.length>64)kb=_sha1(kb);
  while(kb.length<64)kb.push(0);
  var ipad=[],opad=[];
  for(var i=0;i<64;i++){ipad.push(kb[i]^0x36);opad.push(kb[i]^0x5c);}
  var inner=_sha1(ipad.concat(_strBytes(msg)));
  return _b64(_sha1(opad.concat(inner)));
}

function enc(s){ return encodeURIComponent(String(s)).replace(/[!*'()]/g, c=>'%'+c.charCodeAt(0).toString(16).toUpperCase()); }
async function xreq(method, baseUrl, qs, jsonBody){
  qs = qs || {};
  const oauth = {
    oauth_consumer_key: CK,
    oauth_nonce: Date.now().toString(16)+Math.random().toString(16).slice(2,10),
    oauth_signature_method: 'HMAC-SHA1',
    oauth_timestamp: Math.floor(Date.now()/1000).toString(),
    oauth_token: AT,
    oauth_version: '1.0'
  };
  const all = Object.assign({}, qs, oauth);
  const pstr = Object.keys(all).sort().map(k=>enc(k)+'='+enc(all[k])).join('&');
  const base = method.toUpperCase()+'&'+enc(baseUrl)+'&'+enc(pstr);
  const key = enc(CS)+'&'+enc(AS);
  oauth.oauth_signature = hmacSha1B64(key, base);
  const header = 'OAuth '+Object.keys(oauth).sort().map(k=>enc(k)+'="'+enc(oauth[k])+'"').join(', ');
  const qparts = Object.keys(qs).map(k=>enc(k)+'='+enc(qs[k])).join('&');
  const url = qparts ? baseUrl+'?'+qparts : baseUrl;
  const opts = { method, url, headers: { Authorization: header }, json: true, returnFullResponse: true, ignoreHttpStatusErrors: true };
  if (jsonBody!==undefined && jsonBody!==null){ opts.body = jsonBody; opts.headers['Content-Type']='application/json'; }
  try { const r = await H.httpRequest(opts); return { status: r.statusCode, body: r.body }; }
  catch(e){ const st=(e&&e.httpCode)||(e&&e.response&&e.response.statusCode)||0; const bd=(e&&e.response&&e.response.body)||(e&&e.cause)||(e&&e.message)||String(e); return { status: st, body: bd, __err:true }; }
}

const sd=$getWorkflowStaticData('global'); const ds=sd.drafts||[];
const id=(($json.body)||{}).id;
const d=ds.find(x=>x.id===id && x.kind==='x_post');
if(!d) return [{json:{summary:`No X draft ${id} found. Use x_list_drafts to see pending drafts.`}}];
if(d.status==='published') return [{json:{summary:`X draft ${id} was already published as tweet ${d.tweetId||'(unknown)'}.`}}];
if((d.text||'').length>280) return [{json:{summary:`X draft ${id} is ${(d.text||'').length} chars (>280); shorten it before publishing.`}}];
const r=await xreq('POST','https://api.twitter.com/2/tweets',{},{text:d.text});
let body=r.body; if(typeof body==='string'){ try{ body=JSON.parse(body); }catch(e){} }
if(r.status===200 || r.status===201){
  const tid=body&&body.data&&body.data.id;
  d.status='published'; d.tweetId=tid; d.publishedAt=new Date().toISOString();
  return [{json:{summary:`Published X draft ${id} as tweet ${tid}: ${(d.text||'').replace(/\s+/g,' ').slice(0,80)}`, tweetId:tid}}];
}
const detail=(body&&(body.detail||body.title))|| (r.msg||('HTTP '+(r.status||'error')));
